/* Generated by Trae Work */
/* 高中数学页：章节讲解 + 例题步骤 + 图例 + 交互式章节测验（进度存 localStorage） */
"use strict";
(function () {
  const GROUPS = ["衔接", "高一上（必修一）", "高一下（必修二）", "高二上（选择性必修一）", "高二下（选择性必修二）", "高三（选择性必修三）"];

  function chapters() { return (window.MATH_CHAPTERS || []).slice().sort((a, b) => a.id.localeCompare(b.id)); }

  function quizDone() { return Store.get("math_quiz_done", {}); }

  function renderSide() {
    const chs = chapters(), done = quizDone();
    const nSec = chs.reduce((s, c) => s + (c.sections || []).length, 0);
    const nEx = chs.reduce((s, c) => s + (c.examples || []).length, 0);
    const nQ = chs.reduce((s, c) => s + (c.quiz || []).length, 0);
    const stats = `<div class="nt-stat">共 ${chs.length} 章 · ${nSec} 小节讲解 · ${nEx} 道例题 · ${nQ} 题测验</div>`;
    const groups = GROUPS.map(g => {
      const list = chs.filter(c => c.grade === g);
      if (!list.length) return "";
      return `<div class="nt-group"><div class="nt-group-title">${g}</div>${list.map(c => {
        const d = done[c.id], pass = d && d.score / d.total >= 0.8;
        return `<a class="nt-item${location.hash === "#" + c.id ? " active" : ""}" href="#${c.id}">${c.title}${pass ? `<span class="nt-check" title="测验 80% 以上">✓</span>` : ""}</a>`;
      }).join("")}</div>`;
    }).join("");
    document.getElementById("math-side").innerHTML = stats + groups;
  }

  function exampleHtml(ex, idx) {
    return `<div class="m-ex">
      <div class="m-ex-tag">例题 ${idx}</div>
      <div class="m-ex-q">${ex.q}</div>
      <ol class="m-steps">${(ex.steps || []).map(s => `<li>${s}</li>`).join("")}</ol>
      ${ex.ans ? `<div class="m-ex-ans">答案：${ex.ans}</div>` : ""}
    </div>`;
  }

  function quizHtml(ch) {
    const done = quizDone()[ch.id];
    return `<section class="m-quiz" id="quiz-${ch.id}">
      <h3>章节测验 · ${ch.title}</h3>
      <p class="m-quiz-hint">点选项立刻判对错；填空题先写在纸上，再点「看答案」。答错就回到上面重读对应小节。</p>
      ${done ? `<div class="m-score" id="score-${ch.id}">上次成绩：${done.score} / ${done.total}${done.score / done.total >= 0.8 ? "（已达标 ✓）" : "（未达 80%，建议重做）"}</div>` : ""}
      ${(ch.quiz || []).map((q, i) => {
        let body;
        if (q.options && q.options.length) {
          body = `<div class="q-opts">${q.options.map((o, j) => `<button class="opt" data-i="${i}" data-j="${j}">${"ABCD"[j]}. ${o}</button>`).join("")}</div>`;
        } else {
          body = `<button class="opt ans-toggle" data-i="${i}">看答案</button>`;
        }
        return `<div class="m-q" data-q="${i}">
          <div class="q-t"><strong>第 ${i + 1} 题</strong>　${q.q}</div>
          ${body}
          <div class="m-why" id="why-${ch.id}-${i}">解析：${q.why || ""}${q.ans && !(q.options && q.options.length) ? `｜答案：<strong>${q.ans}</strong>` : ""}</div>
        </div>`;
      }).join("")}
      <button class="btn small" id="quiz-reset-${ch.id}" style="margin-top:10px;">重做本章测验</button>
    </section>`;
  }

  function renderChapter() {
    const root = document.getElementById("math-detail");
    const id = location.hash.replace("#", "");
    const ch = chapters().find(c => c.id === id);
    if (!ch) {
      const chs = chapters();
      root.innerHTML = `<h2>选一门课程章节开始学习</h2>
        <p class="muted" style="margin:10px 0 4px;">本页覆盖高中数学全部主干内容（人教 A 版新教材结构）：从「初中打底」衔接章开始，经高一（函数、三角、向量、立体几何、统计概率）、高二（空间向量、直线圆、圆锥曲线、数列、导数），到高三（计数原理、随机变量、成对数据统计分析）。</p>
        <p class="muted">完全零基础也能学：讲解全部用大白话 + 生活例子，例题给出每一步为什么这么算。建议顺序学习，每章学完立刻做测验。</p>
        <div class="m-ex" style="margin-top:14px;"><div class="m-ex-tag">怎么开始</div><div class="m-ex-q">点左侧「衔接 → 第 0 章 初中打底」，从那里开始往下学就行。每天 1 章的量刚刚好。</div></div>`;
      return;
    }
    root.innerHTML = `
      <div class="nt-chap-badges"><span class="badge kaoyan">${ch.grade}</span><span class="badge code">${(ch.quiz || []).length} 题测验 · ${(ch.examples || []).length} 道例题</span></div>
      <h2>${ch.title}</h2>
      ${ch.intro ? `<p class="muted" style="margin:8px 0;">${ch.intro}</p>` : ""}
      ${(ch.sections || []).map((s, i) => `
        <section class="m-sec">
          <h3>${i + 1}. ${s.title}</h3>
          <div class="m-text">${s.text}</div>
          ${s.fig ? `<figure class="m-fig">${s.fig.svg}<figcaption class="cap">${s.fig.caption}</figcaption></figure>` : ""}
          ${s.example ? exampleHtml(s.example, i + 1) : ""}
        </section>`).join("")}
      ${(ch.examples || []).length ? `<h3 style="margin-top:20px;">综合例题（先自己做，再看步骤）</h3>${ch.examples.map((e, i) => exampleHtml(e, i + 1)).join("")}` : ""}
      ${quizHtml(ch)}`;
    bindQuiz(ch);
    renderSide();
    if (window.renderMathInElement) {
      renderMathInElement(root, {
        delimiters: [
          { left: "$$", right: "$$", display: true },
          { left: "$", right: "$", display: false }
        ],
        throwOnError: false
      });
    }
  }

  function bindQuiz(ch) {
    const done = quizDone();
    let score = 0, answered = 0;
    const total = (ch.quiz || []).length;
    function record(earned) {
      if (earned) score++;
      answered++;
      if (answered === total) {
        done[ch.id] = { score, total };
        Store.set("math_quiz_done", done);
        const sc = document.getElementById("score-" + ch.id);
        if (sc) sc.textContent = `本次成绩：${score} / ${total}${score / total >= 0.8 ? "（已达标 ✓）" : "（未达 80%，建议重做）"}`;
        renderSide();
      }
    }
    document.querySelectorAll(`#quiz-${ch.id} .m-q`).forEach(qEl => {
      const i = +qEl.dataset.q, q = ch.quiz[i];
      qEl.querySelectorAll(".opt").forEach(btn => {
        btn.addEventListener("click", () => {
          if (qEl.dataset.done === "1") return;
          const why = document.getElementById(`why-${ch.id}-${i}`);
          if (btn.classList.contains("ans-toggle")) { /* 填空题 */
            qEl.dataset.done = "1";
            btn.textContent = "已看过答案";
            btn.disabled = true;
            why.classList.add("show");
            record(false);
            return;
          }
          qEl.dataset.done = "1";
          const j = +btn.dataset.j;
          if (j === q.a) { btn.classList.add("correct"); record(true); }
          else {
            btn.classList.add("wrong");
            qEl.querySelectorAll(".opt").forEach(b => { if (+b.dataset.j === q.a) b.classList.add("correct"); });
            record(false);
          }
          why.classList.add("show");
        });
      });
    });
    const reset = document.getElementById("quiz-reset-" + ch.id);
    if (reset) reset.addEventListener("click", () => {
      const d = quizDone(); delete d[ch.id]; Store.set("math_quiz_done", d);
      renderChapter();
    });
  }

  window.addEventListener("hashchange", renderChapter);
  document.addEventListener("DOMContentLoaded", () => {
    if (!location.hash && chapters().length) location.hash = chapters()[0].id;
    renderChapter();
  });
})();
